<div class="row g-4 debt-consolidation-calculator-rebuilt"><div class="col-lg-12"><div class="calculator-card"><div class="calculator-body"><div class="row g-3"><div class="col-md-6"><label class="form-label-custom">Total Existing Debt ($)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="dc-total" class="form-control form-control-lg" value="25000" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Current Monthly Payments ($)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="dc-current" class="form-control form-control-lg" value="800" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">New Consolidated Rate (%)</label><div class="input-group"><input type="number" id="dc-newrate" class="form-control form-control-lg" value="8" min="0"><span class="input-group-text bg-light fw-bold">%</span></div></div><div class="col-md-6"><label class="form-label-custom">New Term (Months)</label><div class="input-group"><input type="number" id="dc-term" class="form-control form-control-lg" value="48" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Origination Fee (%)</label><div class="input-group"><input type="number" id="dc-fee" class="form-control form-control-lg" value="2" min="0"><span class="input-group-text bg-light fw-bold">%</span></div></div></div></div></div></div><div class="col-lg-12"><div class="output-card-themed" style="--tool-hue:260;--tool-color:#8b5cf6;--tool-bg:rgba(0,0,0,.02);"><div class="output-hero"><span class="output-hero-label">Debt Consolidation Calculator</span><div class="output-hero-value" id="debt-val">—</div><span class="output-hero-unit" id="debt-st">—</span></div><div class="row g-3 mt-3"><div class="col-md-3"><div class="stat-card" style="border-color:#8b5cf6;background:rgba(0,0,0,.02);"><span class="stat-card-label">NEW PAYMENT</span><span class="stat-card-value" style="color:#8b5cf6" id="dc-newpmt">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#22c55e;background:rgba(0,0,0,.02);"><span class="stat-card-label">MONTHLY SAVINGS</span><span class="stat-card-value" style="color:#22c55e" id="dc-savings">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#ef4444;background:rgba(0,0,0,.02);"><span class="stat-card-label">TOTAL INTEREST</span><span class="stat-card-value" style="color:#ef4444" id="dc-total-i">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#3b82f6;background:rgba(0,0,0,.02);"><span class="stat-card-label">TOTAL SAVED</span><span class="stat-card-value" style="color:#3b82f6" id="dc-total-s">—</span></div></div></div><div class="mt-4" id="debt-ins"></div><div class="row g-2 mt-4"><div class="col-md-4"><button class="btn d-block mx-auto btn-dark py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="debt-cp"><i class="fas fa-copy me-2"></i>Copy Summary</button></div><div class="col-md-4"><button class="btn d-block mx-auto btn-outline-dark py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="debt-rs"><i class="fas fa-rotate-left me-2"></i>Reset</button></div><div class="col-md-4"><button class="btn d-block mx-auto btn-outline-primary py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="debt-cb"><i class="fas fa-calculator me-2"></i>Calculate</button></div></div></div></div></div>
<script>document.addEventListener("DOMContentLoaded",function(){const $=id=>document.getElementById(id);function fmt(v){return"$"+Math.round(v).toLocaleString();}function calc(){const debt=parseFloat($("dc-total").value)||0,cur=parseFloat($("dc-current").value)||0,nr=(parseFloat($("dc-newrate").value)||0)/100/12,term=parseFloat($("dc-term").value)||1,fee=(parseFloat($("dc-fee").value)||0)/100;const principal=debt*(1+fee);const pmt=nr>0?principal*(nr*Math.pow(1+nr,term))/(Math.pow(1+nr,term)-1):principal/term;const moSave=cur-pmt;const totalInt=pmt*term-debt;const totalSave=moSave*term;$("debt-val").textContent=fmt(pmt)+"/mo";$("dc-newpmt").textContent=fmt(pmt);$("dc-savings").textContent=fmt(moSave)+"/mo";$("dc-total-i").textContent=fmt(totalInt);$("dc-total-s").textContent=fmt(totalSave);$("debt-st").textContent=moSave>0?"SAVES MONEY":"COSTS MORE";$("debt-st").style.color=moSave>0?"#22c55e":"#ef4444";let ins=[];ins.push("New payment: <strong>"+fmt(pmt)+"/mo</strong> vs current "+fmt(cur)+"/mo.");ins.push(moSave>0?"You save <strong>"+fmt(moSave)+"/mo</strong> ("+fmt(totalSave)+" total).":"⚠️ Consolidation costs more. Consider shorter term.");$("debt-ins").innerHTML='<h6 class="fw-bold mb-2"><i class="fas fa-lightbulb me-2 text-warning"></i>Analysis</h6><ul class="list-unstyled mb-0 small">'+ins.map(x=>'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>'+x+'</li>').join("")+'</ul>';}['dc-total','dc-current','dc-newrate','dc-term','dc-fee'].forEach(id=>$(id).addEventListener("input",calc));$("debt-cb").addEventListener("click",calc);$("debt-cp").addEventListener("click",function(){navigator.clipboard.writeText("Debt Consolidation Calculator: "+$("debt-val").textContent).then(()=>{const o=this.innerHTML;this.innerHTML='<i class="fas fa-check me-2"></i>Copied!';setTimeout(()=>this.innerHTML=o,2e3);});});$("debt-rs").addEventListener("click",()=>{$("dc-total").value=25000;$("dc-current").value=800;$("dc-newrate").value=8;$("dc-term").value=48;$("dc-fee").value=2;calc();});calc();});</script>
<style>.debt-consolidation-calculator-rebuilt .calculator-card{background:#fff;border:1px solid #e5e7eb;border-radius:20px;padding:2rem;box-shadow:0 4px 24px rgba(0,0,0,.04)}.debt-consolidation-calculator-rebuilt .calculator-header{display:flex;align-items:center;gap:1.25rem;margin-bottom:2rem}.debt-consolidation-calculator-rebuilt .calculator-header h4{margin:0;font-weight:700;font-size:1.1rem;color:#1e293b}.debt-consolidation-calculator-rebuilt .calculator-header p{margin:0;font-size:.85rem;color:#64748b}.debt-consolidation-calculator-rebuilt .tool-icon-circle{width:56px;height:56px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.4rem;flex-shrink:0}.debt-consolidation-calculator-rebuilt .form-label-custom{font-size:.75rem;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:.8px;margin-bottom:.4rem;display:block}</style>